import { readFileSync } from "node:fs";
import { MIGRATIONS_FOLDER, readJournal, splitStatements } from "../migrate";

/** The source of `sql.generated.ts` (see scripts/gen-local-sql.ts). */
export function localSqlSource(): string {
  const migrations = readJournal().map(({ tag }) => ({
    tag,
    statements: splitStatements(readFileSync(`${MIGRATIONS_FOLDER}/${tag}.sql`, "utf8")),
  }));
  const authStub = readFileSync(
    new URL("../../sql/supabase-auth-stub.sql", import.meta.url),
    "utf8",
  );
  return [
    "// Generated by scripts/gen-local-sql.ts from migrations/ and sql/supabase-auth-stub.sql. Do not edit.",
    "/* eslint-disable */",
    `export const AUTH_STUB_SQL: string = ${JSON.stringify(authStub)};`,
    `export const MIGRATION_SQL: readonly { tag: string; statements: readonly string[] }[] = ${JSON.stringify(migrations, null, 1)};`,
    "",
  ].join("\n");
}
